import { withPersistence } from "@/composition/postgres/route";
import { listLoyverseAccounts } from "@/composition/loyverse-accounts";
import { NextResponse } from "next/server";
import { getConfig } from "@/config";
import { createBusinessDatabase } from "@/composition/postgres/service";
import {
  getGoogleSheetsSalesDashboard,
  isValidBangkokSalesDate,
} from "@/modules/sales/server";

export const runtime = "nodejs";

async function GETOperation(request: Request): Promise<NextResponse> {
  try {
    const config = getConfig();
    const accounts = (await listLoyverseAccounts(config)).map(({ id, shopName }) => ({
      id,
      shopName,
    }));
    const { searchParams } = new URL(request.url);
    const accountIds = [
      ...new Set(
        (searchParams.get("accounts") || "")
          .split(",")
          .map((value) => value.trim())
          .filter(Boolean),
      ),
    ];
    if (
      accountIds.some(
        (accountId) => !accounts.some((account) => account.id === accountId),
      )
    ) {
      return NextResponse.json(
        { ok: false, error: "Sales account not found." },
        { status: 404 },
      );
    }

    const today = getBangkokDate();
    const fromDate =
      searchParams.get("from")?.trim() || `${today.slice(0, 7)}-01`;
    const toDate = searchParams.get("to")?.trim() || today;
    if (
      !isValidBangkokSalesDate(fromDate) ||
      !isValidBangkokSalesDate(toDate) ||
      fromDate > toDate
    ) {
      return NextResponse.json(
        { ok: false, error: "A valid date range is required." },
        { status: 400 },
      );
    }

    const dashboard = await getGoogleSheetsSalesDashboard({
      accountIds: accountIds.length ? accountIds : undefined,
      fromDate,
      storage: createBusinessDatabase(),
      toDate,
    });

    return NextResponse.json({
      ok: true,
      source: "google_sheets",
      fromDate,
      toDate,
      accountIds,
      accounts,
      ...dashboard,
    });
  } catch (error) {
    console.error("Failed to load sales dashboard from Google Sheets", {
      error: getErrorMessage(error),
    });
    return NextResponse.json(
      { ok: false, error: "Failed to load sales dashboard from Google Sheets." },
      { status: 500 },
    );
  }
}

function getBangkokDate(): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    day: "2-digit",
    month: "2-digit",
    timeZone: "Asia/Bangkok",
    year: "numeric",
  }).formatToParts(new Date());
  const year = parts.find((part) => part.type === "year")?.value || "";
  const month = parts.find((part) => part.type === "month")?.value || "";
  const day = parts.find((part) => part.type === "day")?.value || "";
  return `${year}-${month}-${day}`;
}

function getErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export const GET = withPersistence(GETOperation);

src/app/api/sales/profit-summary/route.t.before:
import { withPersistence } from "@/composition/postgres/route";
import { listLoyverseAccounts } from "@/composition/loyverse-accounts";
import { NextResponse } from "next/server";
import { getConfig } from "@/config";
import { createBusinessDatabase } from "@/composition/postgres/service";
import {
  getGoogleSheetsProfitSummary,
  listSalesProfitCostOverrides,
} from "@/modules/sales/server";

import { listExpenses, listExpenseShops } from "@/modules/expenses/server";

export const runtime = "nodejs";

async function GETOperation(request: Request): Promise<NextResponse> {
  const { searchParams } = new URL(request.url);
  const year = searchParams.get("year")?.trim() || getBangkokYear();
  if (!isValidYear(year)) {
    return NextResponse.json(
      { ok: false, error: "Enter a valid profit summary year." },
      { status: 400 },
    );
  }

  try {
    const config = getConfig();
    const configuredAccounts = (await listLoyverseAccounts(config)).map(({ id, shopName }) => ({
      id,
      shopName,
    }));
    const storage = createBusinessDatabase();
    const [expenses, costOverrides, shops] = await Promise.all([
      listExpenses({ storage, year }),
      listSalesProfitCostOverrides({ storage, year }),
      listExpenseShops(storage),
    ]);
    const accountMap = new Map(configuredAccounts.map(account => [account.id, account]));
    for (const shop of shops) {
      const id = shop.loyverseAccountId || shop.id;
      accountMap.set(id, { id, shopName: shop.name });
    }
    const accounts = [...accountMap.values()];
    const summary = await getGoogleSheetsProfitSummary({
      accounts,
      costOverrides,
      expenses,
      storage,
      year,
    });
    return NextResponse.json({
      ok: true,
      source: "google_sheets",
      accounts,
      ...summary,
    });
  } catch (error) {
    console.error("Failed to load sales profit summary", {
      year,
      error: error instanceof Error ? error.message : String(error),
    });
    return NextResponse.json(
      { ok: false, error: "Failed to load sales profit summary." },
      { status: 500 },
    );
  }
}

function getBangkokYear(): string {
  return new Intl.DateTimeFormat("en-US", {
    timeZone: "Asia/Bangkok",
    year: "numeric",
  }).format(new Date());
}

function isValidYear(value: string): boolean {
  return /^\d{4}$/.test(value) && Number(value) >= 2000 && Number(value) <= 2100;
}

export const GET = withPersistence(GETOperation);

